"use server";
import { revalidatePath } from "next/cache";

// サードパーティのパッケージの Server Actions
const entries = [];

export async function addEntry(formData) {
  entries.push(String(formData.get("entry")));
  revalidatePath("/third-party/actions");
}

export async function listEntries() {
  return [...entries];
}

export async function resetEntries() {
  entries.length = 0;
}
